</div>',
      title = 'Review the Contacts Page',
      lesson_number = 2,
      sort_order = 2,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Review the Contacts Page';
